# function to detect first touch within a window and reaction
def detect_zone_touch_and_reaction(zone_low, zone_high, start_time, end_time, max_forward_candles=2):
    touched = False
    touch_idx = None
    touch_time = None
    touch_close = None
    reaction = False
    direction = "resistance" if zone_low>start_close else "support" if zone_high<start_close else "neutral"
    # find first candle in window that touches (high >= low and low <= high)
    for i,c in enumerate(candles):
        if c["time"] < start_time or c["time"] > end_time:
            continue
        if c["high"] >= zone_low and c["low"] <= zone_high:
            touched = True
            touch_idx = i
            touch_time = c["time"]
            touch_close = c["close"]
            # check up to next max_forward_candles
            for j in range(1, max_forward_candles+1):
                if touch_idx + j < len(candles):
                    c2 = candles[touch_idx+j]
                    # ensure within overall dataset (no time window for reaction? restrict to end_time+? We'll allow within dataset)
                    if direction == "support":
                        # reaction means close rises by >=0.5% relative to touch_close
                        if (c2["close"] - touch_close) / touch_close >= 0.005:
                            reaction = True
                            break
                    elif direction == "resistance":
                        if (touch_close - c2["close"]) / touch_close >= 0.005:
                            reaction = True
                            break
                    else:
                        # neutral: if upward movement >=0.5% mark as reaction up, or downward mark reaction down
                        if abs((c2["close"] - touch_close)/touch_close) >= 0.005:
                            reaction = True
                            break
            break
    return {"touched": touched, "touch_time": touch_time, "touch_close": touch_close, "reaction": reaction, "direction": direction}

