# Reaction detection function
def detect_touch_and_reaction(level_type, low_bound, high_bound, candles_window, reaction_thresh=0.006, lookahead=3):
    # level_type: 'support' or 'resistance'
    touched = False
    reaction = False
    touch_times = []
    for i,c in enumerate(candles_window):
        if level_type=='support':
            if c['low'] <= high_bound:
                touched=True
                touch_times.append((i,c))
        else:
            if c['high'] >= low_bound:
                touched=True
                touch_times.append((i,c))
    # check reaction for each touch
    for idx, touch in touch_times:
        touch_close = touch['close']
        for j in range(1, lookahead+1):
            if idx + j < len(candles_window):
                future_close = candles_window[idx+j]['close']
                if level_type=='support':
                    if future_close >= touch_close*(1+reaction_thresh):
                        reaction=True
                        break
                else:
                    if future_close <= touch_close*(1-reaction_thresh):
                        reaction=True
                        break
        if reaction:
            break
    return touched, reaction, touch_times

